import json,hashlib,datetime
from pathlib import Path
L=Path(__file__).resolve().parent
def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,j):(L/n).write_text(json.dumps(j,indent=2)+'\n')
utc=datetime.datetime.now(datetime.timezone.utc).isoformat()
guard=L.parent/'sol-edge-irregulator-manuscript-packet-r1/packet/helper_guard.py'
prefix='OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 PYTHONDONTWRITEBYTECODE=1 python3 '+str(guard)+' python3 '
save('provenance.json',dict(utc=utc,status='ZERO_ELIGIBLE_NOMINEES',counts=dict(additional=9,total=39,next=40,credit=0),lane=str(L),guard=dict(path=str(guard),sha256=h(guard),AS_bytes=512*1024**2,group_sampled_RSS_bytes=512*1024**2,CPU_seconds=210,wall_seconds=230,unchanged=True),run_checks=prefix+str(L/'checks.py'),run_verify=prefix+str(L/'verify.py'),http_receipts='http.jsonl',cached_counterparts='cached-receipts.json',history='history-receipt.json',early_screens=['early-screen.json','second-screen.json','third-screen.json'],limits=['Qualified index is bounded; no all-history completeness','Live denied registries not retried; fixed capped intervals and missing merge trees PARKED','Weighted-bond retirement inherited from original r131 disposition, only Conjecture4.13(2)','Cayley current abstract v1; counterexample latest observed arXiv v2; no journal VoR authentication claimed','Archived context copies frozen; live NEXT/ledger excluded from immutable science'],failures=['Companion guessed 2024 Opuscula PDF404','Distinct sensitivity published-copy404','Native rg referenced two nonexistent r131 receipt names; corrected to provenance.json'],prohibited_actions_performed=[]))
save('search-record.json',dict(recorded_utc=utc,method='Public web search/fetch tools; no browser. Exact HTTP body times in http.jsonl; individual search tool times not separately captured.',queries=['arxiv graph conjecture "2026" "Conjecture" "saturation" combinatorics','arxiv "conjecture" "2025" "independent domination"','"Augmenting graphs to partition" conjecture authors','"Augmenting graphs to partition" "conjecture" proof','site.arxiv.org "conjecture" "2026" "polynomial" "graph" "log-concave"','site.opuscula.agh.edu.pl "2025" "Conjecture" "matching"','site.arxiv.org/abs/2610 "conjecture" "graph" "We conjecture"','site.arxiv.org/abs/2609 "conjecture" "matching" "We conjecture"','"Potechin" "Tsang" Cayley conjecture counterexample','"A Conjecture on Induced Subgraphs of Cayley Graphs" journal','"Alon" "Zheng" "Cayley" 2020 induced subgraphs'],decisive_primary_urls=['https://arxiv.org/abs/2003.13166','https://arxiv.org/abs/2004.01327','https://arxiv.org/abs/2009.00554','https://web.math.princeton.edu/~nalon/PDFS/inducedc7.pdf'],limits='Search snippets are leads only. Unselected results were not adopted as statements. Actual primary/companion body receipts, not search snippets, govern Cayley disposition.'))
exclude=['scientific-freeze.json','finalmanifest.json','scientific-verification.json','manifest-verification.json']
files=sorted(p for p in L.rglob('*') if p.is_file() and p.relative_to(L).as_posix() not in exclude)
rows=[dict(path=p.relative_to(L).as_posix(),sha256=h(p),bytes=p.stat().st_size) for p in files]
save('scientific-freeze.json',dict(utc=utc,records=rows,exclusions=exclude,policy='All lane payload including scientific originals, copies, scripts, reports, and archived administrative snapshots. Live administrative originals not in lane are not immutable.'))
save('finalmanifest.json',dict(utc=utc,records=rows+[dict(path='scientific-freeze.json',sha256=h(L/'scientific-freeze.json'),bytes=(L/'scientific-freeze.json').stat().st_size)],exclusions=['finalmanifest.json','scientific-verification.json','manifest-verification.json'],self_exclusion='finalmanifest.json cannot hash itself; two independent receipt outputs excluded explicitly. No stdout files.'))
print(json.dumps(dict(utc=utc,scientific=len(rows),manifest=len(rows)+1)))
